#include "../src/residual.hpp"
#include "fast_poly.hpp"
Poly randompoly(int n,int seed){Poly a;a.c.resize(n+1);for(int i=0;i<=n;i++)a.c[i]=F::code((1789LL*i*i+3456*i+113LL*seed)%kfield::ORDER);if(!a.c.back())a.c.back()=F(1);return a;}
int main(){try{input::init();for(auto [n,m]:std::vector<std::pair<int,int>>{{1,2},{2,2},{0,0},{2,1},{20,8},{100,87},{129,128},{130,129},{200,199},{300,250},{501,500},{1000,999},{2010,1111}}){auto a=randompoly(n,13),b=randompoly(m,99);if(fmul(a,b)!=a*b)throw std::runtime_error("mul reference");auto[q,r]=fdivrem(a,b);if(a.divrem(b)!=std::make_pair(q,r))throw std::runtime_error("div reference");auto[g,s,t]=fxgcd(a,b);if(g!=gcd(a,b))throw std::runtime_error("gcd reference");auto z=randompoly(5,233);auto[g2,s2,t2]=fxgcd(fmul(a,z),fmul(b,z));if(g2!=z/z.c.back())throw std::runtime_error("nontrivial gcd");std::cout<<"degrees="<<n<<","<<m<<" multiply/divide/xgcd reference and common-factor PASS\n";}
 for(int n:{5000,5001,11001}){auto a=randompoly(n,71),b=randompoly(n-1,91),z=randompoly(17,213);auto aa=fmul(a,z),bb=fmul(b,z);auto[g,s,t]=fxgcd(aa,bb);if(g!=z/z.c.back())throw std::runtime_error("large common gcd");for(int c:{1,23,211})if(fmul(a,b).eval(F::code(c))!=a.eval(F::code(c))*b.eval(F::code(c)))throw std::runtime_error("product eval");std::cout<<"large degrees="<<n<<" Bezout, divisibility and common-factor PASS\n";}
 return 0;}catch(std::exception&e){std::cerr<<"ERROR: "<<e.what()<<"\n";return 1;}}
